import builtins, time, numpy as np
from nuka.editor.app import ActionError
def frames(n):
    for _ in range(n):
        app.update(True)
def tick():
    return app.actions.run('timeline.status')['tick']
def step(n):
    t = tick()
    app.actions.run('sim.step', steps=n)
    deadline = time.monotonic() + 60.0
    while tick() < t + n:
        assert time.monotonic() < deadline, tick()
        app.update(True)
    frames(3)
def fails(action, text, **args):
    try:
        app.actions.run(action, **args)
    except ActionError as e:
        assert text in str(e), (action, args, str(e))
    else:
        raise AssertionError((action, args))
def heights():
    placement, values = app.world.terrain()
    return placement, placement['base_z'] + np.asarray(values, np.float64) * placement['scale_z']
for k, v in dict(frames=frames, tick=tick, step=step, fails=fails, heights=heights).items():
    setattr(builtins, 'tr_' + k, v)
assert app.actions.run('scene.terrain_info') is None
f = fails
f('scene.terrain', 'the terrain kind is flat, bumps, slope, stairs or mixed', kind='hills')
f('scene.terrain', 'a terrain side spans 4 to 4096 cells', kind='flat', cell=0.01)
f('scene.terrain', 'bumps need a height above 0', kind='bumps', height=0.0)
f('scene.terrain', 'stairs need a rise other than 0', kind='stairs', rise=0.0)
f('scene.terrain', 'the scene has no terrain', kind='none')
f('sim.dt', 'seconds: 0.0001 to 0.05', seconds=0.5)

